import controlador.*;
import modelo.*;
import gui.BibliotecaApp;
import gui.controllers.*;
import javafx.application.*;
import javafx.scene.*;
import javafx.scene.control.*;
import javafx.scene.image.*;
import javafx.stage.*;
import javafx.animation.*;
import javafx.util.Duration;
import javafx.embed.swing.SwingFXUtils;
import javax.imageio.ImageIO;
import java.lang.reflect.*;
import java.nio.file.*;
import java.util.*;

public class PruebasGui extends Application {
    static Path evidence;static int exitStatus;Stage primary;int passed,failed,errors;List<String> results=new ArrayList<>();List<String> dialogs=new ArrayList<>();
    GestorLibros gl;GestorUsuarios gu;GestorPrestamos gp;GestorReservas gr;
    interface Check {String run() throws Exception;}
    static void expect(boolean condition,String detail){if(!condition)throw new AssertionError(detail);}
    void test(String id,String title,Check c){
        String status,detail;try{detail=c.run();status="OK";passed++;}catch(AssertionError e){status="FALLO";detail=e.getMessage();failed++;}catch(Throwable e){status="ERROR";detail=e.toString();errors++;e.printStackTrace();}
        String row=String.join("\t",id,status,title,detail.replace('\n',' ').replace('\t',' '));results.add(row);System.out.println(row);
    }
    void seed()throws Exception{
        BibliotecaApp.cerrarSesion();SoporteBD.reiniciar();
        gui.TareasBD.invocar(()->{BibliotecaApp.abrir(SoporteBD.sesion());return null;});
        gl=BibliotecaApp.getGestorLibros();gu=BibliotecaApp.getGestorUsuarios();gp=BibliotecaApp.getGestorPrestamos();gr=BibliotecaApp.getGestorReservas();
        gl.agregarLibro(new Libro("L1","Zeta","Autor","9780307474728",2000,"Ficcion"));gl.agregarLibro(new Libro("L2","Alfa","Autor","9780307474728",2001,"Historia"));
        gu.agregarUsuario(new Usuario("A","Ana QA","a@example.com",3));gu.agregarUsuario(new Usuario("B","Bruno QA","b@example.com",3));gu.agregarUsuario(new Usuario("C","Carla QA","c@example.com",3));dialogs.clear();
    }
    void persist()throws Exception{BibliotecaApp.sistema().validar();}
    void show(Node root){primary.setScene(new Scene((Parent)root,1200,700));primary.setTitle("QA Biblioteca - copia de pruebas");primary.show();primary.getScene().getRoot().applyCss();primary.getScene().getRoot().layout();}
    static List<Node> all(Node n){List<Node> r=new ArrayList<>();r.add(n);if(n instanceof Parent p)for(Node c:p.getChildrenUnmodifiable())r.addAll(all(c));return r;}
    static List<TextField> fields(Stage s){return all(s.getScene().getRoot()).stream().filter(n->n instanceof TextField).map(n->(TextField)n).toList();}
    static List<ComboBox<?>> combosDelDialogo(Stage stage){
        List<ComboBox<?>> resultado=new ArrayList<>();
        for(Node nodo:all(stage.getScene().getRoot()))if(nodo instanceof ComboBox<?> combo)resultado.add(combo);
        return resultado;
    }
    static Button button(Stage s,String text){return all(s.getScene().getRoot()).stream().filter(n->n instanceof Button b&&b.getText().equals(text)).map(n->(Button)n).findFirst().orElseThrow(()->new IllegalStateException("Boton no encontrado: "+text));}
    static Object invoke(Object o,String name,Class<?>[]types,Object...args)throws Exception{Method m=o.getClass().getDeclaredMethod(name,types);m.setAccessible(true);try{return m.invoke(o,args);}catch(InvocationTargetException e){if(e.getCause() instanceof Exception x)throw x;throw e;}}
    static Object invoke(Object o,String name)throws Exception{return invoke(o,name,new Class<?>[0]);}
    @SuppressWarnings("unchecked") static <T>T field(Object o,String name)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);return(T)f.get(o);}
    void shot(Stage s,String name)throws Exception{s.getScene().getRoot().applyCss();s.getScene().getRoot().layout();WritableImage image=s.getScene().snapshot(null);ImageIO.write(SwingFXUtils.fromFXImage(image,null),"png",evidence.resolve(name+".png").toFile());}
    interface Fill{void run(Stage s)throws Exception;}
    void dialogAction(Object owner,String method,String formTitle,String capture,Fill fill)throws Exception{
        Set<Window> handled=Collections.newSetFromMap(new IdentityHashMap<>());List<Throwable> exceptions=new ArrayList<>();
        Timeline timer=new Timeline(new KeyFrame(Duration.millis(120),event->{
            for(Window w:new ArrayList<>(Window.getWindows()))if(w instanceof Stage s&&s!=primary&&s.isShowing()&&!handled.contains(s)){
                handled.add(s);Platform.runLater(()->{try{
                    if(s.getTitle().equals(formTitle)){fill.run(s);}else{
                        String labels=all(s.getScene().getRoot()).stream().filter(n->n instanceof Label).map(n->((Label)n).getText()).reduce("",(a,b)->a+" "+b);dialogs.add(s.getTitle()+":"+labels);shot(s,capture+"-alerta-"+dialogs.size());
                        if(s.getScene().getRoot() instanceof DialogPane pane && !pane.getButtonTypes().isEmpty())((Button)pane.lookupButton(pane.getButtonTypes().getFirst())).fire();else s.close();
                    }
                }catch(Throwable e){exceptions.add(e);s.close();}});
            }
        }));timer.setCycleCount(Animation.INDEFINITE);timer.play();
        try{invoke(owner,method);}finally{timer.stop();}
        if(!exceptions.isEmpty())throw new RuntimeException(exceptions.getFirst());
    }
    void runTests()throws Exception{
        test("GUI-01","Login carga estilos asociados a sus clases",()->{seed();new LoginController(primary).show();primary.getScene().getRoot().applyCss();primary.getScene().getRoot().layout();shot(primary,"GUI-01-login-original");expect(!primary.getScene().getStylesheets().isEmpty(),"Scene.stylesheets vacio; clases login-* sin hoja CSS (ver captura)");return "Estilos cargados";});
        test("GUI-02","Todos los botones de Libros visibles a 1200x700",()->{seed();show(new LibrosView(gl));shot(primary,"GUI-02-libros");Button b=button(primary,"Eliminar Libro");double x=b.localToScene(b.getBoundsInLocal()).getMaxX();expect(x<=primary.getScene().getWidth(),"Extremo Eliminar Libro="+x+", ancho escena="+primary.getScene().getWidth());return "Visibles";});
        test("GUI-03","Todos los botones de Usuarios visibles a 1200x700",()->{seed();show(new UsuariosView(gu));shot(primary,"GUI-03-usuarios");Button b=button(primary,"Eliminar Usuario");double x=b.localToScene(b.getBoundsInLocal()).getMaxX();expect(x<=primary.getScene().getWidth(),"Extremo Eliminar Usuario="+x+", ancho escena="+primary.getScene().getWidth());return "Visibles";});
        test("GUI-04","Todos los botones de Prestamos visibles a 1200x700",()->{seed();show(new PrestamosView(gp,gl,gu));shot(primary,"GUI-04-prestamos");Button b=button(primary,"Cancelar Préstamo");double x=b.localToScene(b.getBoundsInLocal()).getMaxX();expect(x<=primary.getScene().getWidth(),"Extremo Cancelar Prestamo="+x+", ancho escena="+primary.getScene().getWidth());return "Visibles";});
        test("GUI-05","Todos los botones de Reportes visibles a 1200x700",()->{seed();show(new ReportesView(gl,gu,gp));shot(primary,"GUI-05-reportes");Button b=button(primary,"🗑️ Limpiar");double x=b.localToScene(b.getBoundsInLocal()).getMaxX();expect(x<=primary.getScene().getWidth(),"Extremo Limpiar="+x+", ancho escena="+primary.getScene().getWidth());return "Visibles";});
        test("GUI-06","Alta de libro mediante dialogo real",()->{seed();LibrosView v=new LibrosView(gl);show(v);dialogAction(v,"mostrarDialogoAgregar","Agregar Nuevo Libro","GUI-06",s->{List<TextField> f=fields(s);String[] vals={"QA001","Libro QA","Autor QA","9780307474728","2001","Categoria QA"};expect(f.size()==6,"Campos="+f.size());for(int i=0;i<6;i++)f.get(i).setText(vals[i]);shot(s,"GUI-06-alta-formulario");button(s,"Agregar Libro").fire();});expect(gl.existeLibro("QA001")&&SoporteBD.cargarLibros().size()==3,"No agregado/persistido");return "Libro agregado y guardado";});
        test("GUI-07","Edicion invalida conserva libro original",()->{seed();LibrosView v=new LibrosView(gl);show(v);TableView<Libro> t=field(v,"tablaLibros");t.getSelectionModel().select(0);dialogAction(v,"editarLibroSeleccionado","Editar Libro","GUI-07",s->{List<TextField> f=fields(s);expect(f.size()==5,"Campos="+f.size());f.get(2).setText("ISBN_INVALIDO");shot(s,"GUI-07-edicion-invalida");button(s,"Guardar Cambios").fire();});expect(gl.existeLibro("L1"),"L1 eliminado del gestor tras validacion fallida; alertas="+dialogs);return "Original intacto";});
        test("GUI-08","Edicion de metadatos de libro prestado",()->{seed();gp.registrarPrestamo("A","L1");LibrosView v=new LibrosView(gl);show(v);TableView<Libro> t=field(v,"tablaLibros");t.getSelectionModel().select(0);dialogAction(v,"editarLibroSeleccionado","Editar Libro","GUI-08",s->{fields(s).getFirst().setText("Titulo corregido");button(s,"Guardar Cambios").fire();});expect(gl.buscarLibro("L1").getTitulo().equals("Titulo corregido"),"Edicion bloqueada: "+dialogs);return "Metadatos actualizados";});
        test("GUI-09","Edicion de lector con prestamo activo",()->{seed();gp.registrarPrestamo("A","L1");UsuariosView v=new UsuariosView(gu);show(v);TableView<Usuario> t=field(v,"tablaUsuarios");t.getSelectionModel().select(0);dialogAction(v,"editarUsuarioSeleccionado","Editar Usuario","GUI-09",s->{fields(s).get(1).setText("Ana corregida");button(s,"Guardar Cambios").fire();});expect(gu.buscarUsuario("A").getNombre().equals("Ana corregida"),"Edicion bloqueada: "+dialogs);return "Lector actualizado";});
        test("GUI-10","Posicion FIFO de dos reservas del mismo dia",()->{seed();gp.registrarPrestamo("A","L1");gr.agregarReserva(gu.buscarUsuario("B"),gl.buscarLibro("L1"));Reserva r=gr.agregarReserva(gu.buscarUsuario("C"),gl.buscarLibro("L1"));ReservasView v=new ReservasView(gr,gl,gu);show(v);shot(primary,"GUI-10-reservas-mismo-dia");int pos=(Integer)invoke(v,"obtenerPosicionEnCola",new Class<?>[]{Reserva.class},r);expect(pos==2,"Segunda reserva devuelve posicion="+pos);return "Posicion=2";});
        test("GUI-11","Ordenar tabla Libros por titulo",()->{seed();LibrosView v=new LibrosView(gl);show(v);TableView<Libro> t=field(v,"tablaLibros");TableColumn<Libro,?> col=t.getColumns().get(1);col.setSortType(TableColumn.SortType.ASCENDING);t.getSortOrder().setAll(List.of(col));t.sort();shot(primary,"GUI-11-ordenacion");expect(t.getItems().getFirst().getTitulo().equals("Alfa"),"Primera fila sigue="+t.getItems().getFirst().getTitulo());return "Ordenado";});
        test("GUI-12","Nuevo prestamo queda guardado tras confirmar",()->{seed();PrestamosView v=new PrestamosView(gp,gl,gu);show(v);dialogAction(v,"mostrarDialogoNuevoPrestamo","Registrar Nuevo Préstamo","GUI-12",s->{List<ComboBox<?>> combos=combosDelDialogo(s);combos.get(0).getSelectionModel().select(0);combos.get(1).getSelectionModel().select(0);fields(s).getFirst().setText("14");button(s,"Registrar Préstamo").fire();});int mem=gp.contarPrestamosActivos(),disk=SoporteBD.cargarPrestamos().size();expect(mem==1&&disk==1,"Memoria="+mem+", archivo="+disk+"; cierre abrupto pierde prestamo");return "Guardado";});
        test("GUI-13","Nueva reserva queda guardada tras confirmar",()->{seed();gp.registrarPrestamo("A","L1");persist();ReservasView v=new ReservasView(gr,gl,gu);show(v);dialogAction(v,"mostrarDialogoNuevaReserva","Nueva Reserva","GUI-13",s->{List<ComboBox<?>> combos=combosDelDialogo(s);combos.get(0).getSelectionModel().select(1);combos.get(1).getSelectionModel().select(0);button(s,"Reservar").fire();});expect(gr.contarReservas()==1&&SoporteBD.cargarReservas().size()==1,"Memoria="+gr.contarReservas()+", archivo="+SoporteBD.cargarReservas().size());return "Guardada";});
        test("GUI-14","Siete reportes muestran texto",()->{seed();ReportesView v=new ReportesView(gl,gu,gp);show(v);for(String method:List.of("mostrarReporteGeneral","mostrarReporteLibros","mostrarReporteUsuarios","mostrarReportePrestamos","mostrarTop5Usuarios","mostrarEstadoFinanciero","mostrarReporteCompleto")){invoke(v,method);TextArea a=field(v,"areaReporte");expect(!a.getText().isBlank(),"Reporte vacio: "+method);}shot(primary,"GUI-14-reporte-completo");return "7 reportes no vacios";});
        test("GUI-15","Datos SQL inválidos bloquean carga",()->{seed();SoporteBD.sql("INSERT INTO libros VALUES('BAD','Titulo','Autor','9780307474728',9999,'Categoria')");try{try{SoporteBD.sistema();throw new AssertionError("Permitió datos inválidos");}catch(java.io.IOException esperado){}expect(SoporteBD.contar("libros")==3,"Modificó datos");}finally{SoporteBD.sql("DELETE FROM libros WHERE id='BAD'");}return "Carga bloqueada y filas conservadas";});
        test("GUI-16","Cierre normal persiste estado completo",()->{seed();gp.registrarPrestamo("A","L1");gr.agregarReserva(gu.buscarUsuario("B"),gl.buscarLibro("L1"));BibliotecaApp.cerrarSesion();expect(SoporteBD.cargarPrestamos().size()==1&&SoporteBD.cargarReservas().size()==1&&!SoporteBD.cargarLibros().getFirst().isDisponible()&&SoporteBD.cargarUsuarios().getFirst().getPrestamosActuales()==1,"Archivos inconsistentes");return "Prestamo/reserva/disponibilidad/contador persistidos";});
        test("GUI-17","Alta de usuario mediante dialogo",()->{seed();UsuariosView v=new UsuariosView(gu);show(v);dialogAction(v,"mostrarDialogoAgregar","Agregar Nuevo Usuario","GUI-17",s->{List<TextField> f=fields(s);String[] vals={"D","Diana QA","d@example.com","3"};for(int i=0;i<4;i++)f.get(i).setText(vals[i]);button(s,"Agregar Usuario").fire();});expect(gu.existeUsuario("D")&&SoporteBD.cargarUsuarios().size()==4,"No creado/guardado");return "Creado y guardado";});
        test("GUI-18","Devolucion mediante confirmacion real",()->{seed();Prestamo p=gp.registrarPrestamo("A","L1");persist();PrestamosView v=new PrestamosView(gp,gl,gu);show(v);TableView<Prestamo> t=field(v,"tablaPrestamos");t.getSelectionModel().select(0);dialogAction(v,"devolverPrestamoSeleccionado","Confirmar Devolución","GUI-18",s->button(s,"Devolver").fire());expect(gp.contarPrestamosActivos()==0&&gl.buscarLibro("L1").isDisponible()&&p.getEstado()==Prestamo.EstadoPrestamo.DEVUELTO,"Devolucion fallida");return "Devuelto en memoria";});
        test("GUI-19","Cancelar prestamo mediante confirmacion real",()->{seed();Prestamo p=gp.registrarPrestamo("A","L1");PrestamosView v=new PrestamosView(gp,gl,gu);show(v);TableView<Prestamo> t=field(v,"tablaPrestamos");t.getSelectionModel().select(0);dialogAction(v,"cancelarPrestamoSeleccionado","Confirmar Cancelación","GUI-19",s->button(s,"Cancelar Préstamo").fire());expect(gp.contarPrestamosActivos()==0&&p.getEstado()==Prestamo.EstadoPrestamo.CANCELADO,"Cancelacion fallida");return "Cancelado en memoria";});
        test("GUI-20","Cancelar reserva mediante confirmacion real",()->{seed();gp.registrarPrestamo("A","L1");Reserva r=gr.agregarReserva(gu.buscarUsuario("B"),gl.buscarLibro("L1"));ReservasView v=new ReservasView(gr,gl,gu);show(v);TableView<Reserva> t=field(v,"tablaReservas");t.getSelectionModel().select(0);dialogAction(v,"cancelarReservaSeleccionada","Confirmar Cancelación","GUI-20",s->button(s,"Cancelar Reserva").fire());expect(gr.contarReservas()==0&&r.getEstado()==Reserva.EstadoReserva.CANCELADA,"Cancelacion fallida");return "Cancelada en memoria";});
        test("GUI-21","Busqueda por titulo y limpieza",()->{seed();LibrosView v=new LibrosView(gl);show(v);TextField f=field(v,"txtBuscar");TableView<Libro> t=field(v,"tablaLibros");f.setText("alfa");expect(t.getItems().size()==1&&t.getItems().getFirst().getId().equals("L2"),"Filtro incorrecto");f.clear();expect(t.getItems().size()==2,"No restauro filas");return "Filtra y restaura";});
        test("GUI-22","Dashboard y navegacion seis modulos",()->{seed();DashboardController d=new DashboardController(primary,new Admin(1,"QA","Administrador QA"));d.show();for(String method:List.of("mostrarInicio","mostrarLibros","mostrarUsuarios","mostrarPrestamos","mostrarReservas","mostrarReportes")){invoke(d,method);primary.getScene().getRoot().applyCss();primary.getScene().getRoot().layout();shot(primary,"GUI-22-"+method);}return "6 modulos construidos";});
        test("GUI-23","Textos completos de acciones dentro del Dashboard",()->{seed();DashboardController d=new DashboardController(primary,new Admin(1,"QA","Admin QA"));d.show();List<String> truncated=new ArrayList<>();for(String method:List.of("mostrarLibros","mostrarUsuarios","mostrarPrestamos","mostrarReportes")){invoke(d,method);primary.getScene().getRoot().applyCss();primary.getScene().getRoot().layout();for(Node n:all(primary.getScene().getRoot()))if(n instanceof Button b&&!b.getText().isBlank()){String rendered=all(b).stream().filter(x->x instanceof javafx.scene.text.Text).map(x->((javafx.scene.text.Text)x).getText()).reduce("",String::concat);if((rendered.contains("...")||rendered.contains("…"))&&!b.getText().equals(rendered))truncated.add(method+":"+b.getText()+"=>"+rendered);}}expect(truncated.isEmpty(),String.join("; ",truncated));return "Etiquetas legibles";});
        test("GUI-24","Ordenar tabla Usuarios por nombre descendente",()->{seed();UsuariosView v=new UsuariosView(gu);show(v);TableView<Usuario> t=field(v,"tablaUsuarios");TableColumn<Usuario,?> col=t.getColumns().get(1);col.setSortType(TableColumn.SortType.DESCENDING);t.getSortOrder().setAll(List.of(col));t.sort();expect(t.getItems().getFirst().getNombre().equals("Carla QA"),"Primera fila="+t.getItems().getFirst().getNombre());return "Ordenada";});
        test("GUI-25","Ordenar tabla Prestamos por usuario descendente",()->{seed();gp.registrarPrestamo("A","L1");gp.registrarPrestamo("B","L2");PrestamosView v=new PrestamosView(gp,gl,gu);show(v);TableView<Prestamo> t=field(v,"tablaPrestamos");TableColumn<Prestamo,?> col=t.getColumns().get(1);col.setSortType(TableColumn.SortType.DESCENDING);t.getSortOrder().setAll(List.of(col));t.sort();expect(t.getItems().getFirst().getUsuario().getId().equals("B"),"Primer usuario="+t.getItems().getFirst().getUsuario().getId());return "Ordenada";});
        test("GUI-26","Abrir catalogo y lectores no deja guardado incoherente",()->{seed();gp.registrarPrestamo("A","L1");show(new LibrosView(gl));show(new UsuariosView(gu));int prestamos=SoporteBD.cargarPrestamos().size();boolean disponible=SoporteBD.cargarLibros().getFirst().isDisponible();int contador=SoporteBD.cargarUsuarios().getFirst().getPrestamosActuales();expect(prestamos==1,"Archivo prestamos="+prestamos+"; disponible="+disponible+"; contador="+contador);return "Coherente";});
        test("GUI-27","Sin éxito falso ante rechazo de MySQL",()->{seed();LibrosView v=new LibrosView(gl);show(v);dialogAction(v,"mostrarDialogoAgregar","Agregar Nuevo Libro","GUI-27",st->{List<TextField> f=fields(st);String[] vals={"QA_IO","x".repeat(600),"Autor QA","9780307474728","2001","Categoria"};for(int j=0;j<6;j++)f.get(j).setText(vals[j]);button(st,"Agregar Libro").fire();});expect(dialogs.stream().noneMatch(x->x.startsWith("Éxito:")),"Éxito falso: "+dialogs);expect(!gl.existeLibro("QA_IO")&&SoporteBD.contar("libros")==2,"Sin rollback");return "Fallo informado y rollback verificado";});

        test("GUI-28","Inicio y cierre reales con datos antiguos",()->{seed();BibliotecaApp app=new BibliotecaApp();app.start(primary);expect(primary.isShowing()&&primary.getTitle().contains("Inicio de Sesión"),"No mostró login");shot(primary,"GUI-28-inicio-real");Label pie=all(primary.getScene().getRoot()).stream().filter(n->n instanceof Label l&&l.getText().contains("MySQL")).map(n->(Label)n).findFirst().orElseThrow();expect(pie.localToScene(pie.getBoundsInLocal()).getMaxY()<=primary.getScene().getHeight(),"Pie de login fuera de escena");app.stop();var restaurado=SoporteBD.sistema();expect(restaurado.libros.getTotalLibros()==2&&restaurado.usuarios.getTotalUsuarios()==3,"Reinicio perdió datos");return "Login abierto, cierre guardado y reinicio correcto";});
    }
    @Override public void start(Stage stage){primary=stage;Platform.setImplicitExit(false);Thread.currentThread().setUncaughtExceptionHandler((t,e)->{System.err.println("UNCUGHT "+e);e.printStackTrace();});Platform.runLater(()->{try{runTests();Files.write(evidence.resolve("gui-resultados.tsv"),results);exitStatus=failed+errors>0?1:0;System.out.println("GUI_RESUMEN: OK="+passed+", FALLO="+failed+", ERROR="+errors+", TOTAL="+results.size());}catch(Throwable e){exitStatus=2;e.printStackTrace();}finally{for(Window w:new ArrayList<>(Window.getWindows()))w.hide();Platform.exit();}});}
    public static void main(String[] args){evidence=Path.of(args[0]);launch(args);System.exit(exitStatus);}
}